    box.addEventListener("pointercancel", function(){ down=false; });
    box.addEventListener("touchstart", function(ev){ down=true; at(ev); }, {passive:true});
    box.addEventListener("touchmove", function(ev){ if(down) at(ev); }, {passive:true});
    box.addEventListener("touchend", function(){ down=false; });
